    var sep1 = sep();
    btnUndo = mkBtn('\\u21b6', undo); btnUndo.title = '\u64A4\u9500 (Ctrl+Z)';
    btnRedo = mkBtn('\\u21b7', redo); btnRedo.title = '\u91CD\u505A (Ctrl+Y)';
